WITH with_windows AS (SELECT *, FIRST_VALUE(shipping_fee, TRUE) OVER (PARTITION BY customer_id ORDER BY shipping_fee, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_shipping_fee, ROW_NUMBER() OVER (ORDER BY amount, id) AS row_seq, AVG(shipping_fee) OVER w_part AS shipping_fee_avg_3, RANK() OVER (PARTITION BY status ORDER BY amount DESC NULLS LAST) AS amount_rank FROM orders WINDOW w_part AS (PARTITION BY customer_id, channel ORDER BY order_date, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW)) SELECT s.id, s.customer_id, s.order_date, s.status, s.channel, s.amount, s.discount, s.shipping_fee_avg_3, s.amount_rank, CASE WHEN channel RLIKE '^(mobile|store)$' THEN 'GROUP_A' ELSE 'CORE' END AS channel_zone, (SELECT SUM(x.amount) FROM orders x WHERE x.customer_id = s.customer_id) AS sum_order_amount FROM with_windows s;
